=== FILE: apb_regs.v ===
// apb_regs: APB4 subordinate with four 32-bit read/write registers.
// Implements interface_spec.md per microarchitecture.md (zero wait states,
// no state machine, PSLVERR for unmapped addresses, synchronous active-low reset).
`default_nettype none

module apb_regs #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    localparam integer STRB_WIDTH = DATA_WIDTH / 8;

    // Access phase: the one cycle the response is sampled and a write lands.
    wire access = psel & penable;

    // Address decode: word aligned and inside 0x0..0xC.
    wire mapped = (paddr[1:0] == 2'b00) & ~(|paddr[ADDR_WIDTH-1:4]);

    // Register index.
    wire [1:0] idx = paddr[3:2];

    wire wr = access & pwrite & mapped;
    wire rd = access & ~pwrite & mapped;

    // Byte-enable mask from pstrb: merge(old, data, strb) = old & ~mask | data & mask.
    wire [DATA_WIDTH-1:0] wmask;
    genvar b;
    generate
        for (b = 0; b < STRB_WIDTH; b = b + 1) begin : g_mask
            assign wmask[8*b +: 8] = {8{pstrb[b]}};
        end
    endgenerate

    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else if (wr) begin
            case (idx)
                2'd0:    reg0 <= (reg0 & ~wmask) | (pwdata & wmask);
                2'd1:    reg1 <= (reg1 & ~wmask) | (pwdata & wmask);
                2'd2:    reg2 <= (reg2 & ~wmask) | (pwdata & wmask);
                default: reg3 <= (reg3 & ~wmask) | (pwdata & wmask);
            endcase
        end
    end

    // Combinational read multiplexer.
    reg [DATA_WIDTH-1:0] rd_mux;
    always @(*) begin
        case (idx)
            2'd0:    rd_mux = reg0;
            2'd1:    rd_mux = reg1;
            2'd2:    rd_mux = reg2;
            default: rd_mux = reg3;
        endcase
    end

    assign prdata  = rd ? rd_mux : {DATA_WIDTH{1'b0}};
    assign pready  = 1'b1;
    assign pslverr = access & ~mapped;

`ifdef FORMAL
    // Design-intent assertions; decode written independently of 'mapped'.
    wire f_mapped = (paddr == 0) || (paddr == 4) || (paddr == 8) || (paddr == 12);
    always @(*) begin
        assert (pready == 1'b1);
        if (!(psel && penable)) begin
            assert (pslverr == 1'b0);
            assert (prdata == {DATA_WIDTH{1'b0}});
        end else begin
            assert (pslverr == !f_mapped);
            if (!f_mapped || pwrite)
                assert (prdata == {DATA_WIDTH{1'b0}});
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
