// apb_regs_tb: directed self-checking testbench for apb_regs.
// Drives after the falling edge, samples 1 ns later (before the rising edge).
`timescale 1ns/1ps
`default_nettype none

module apb_regs_tb;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    apb_regs #(
        .ADDR_WIDTH(8),
        .DATA_WIDTH(32)
    ) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    integer        passed;
    integer        failed;
    reg [8*64-1:0] nonce;
    reg [31:0]     model [0:3];

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // ---------------- checking helpers ----------------
    task check_bit(input integer id, input got, input expv);
        begin
            if (got === expv) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check %0d failed at %0t (paddr=0x%02h): got %b expected %b",
                       id, $time, paddr, got, expv);
            end
        end
    endtask

    task check_word(input integer id, input [31:0] got, input [31:0] expv);
        begin
            if (got === expv) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check %0d failed at %0t (paddr=0x%02h): got 0x%08h expected 0x%08h",
                       id, $time, paddr, got, expv);
            end
        end
    endtask

    task quiet_check(input integer id);
        begin
            check_bit(id, pslverr, 1'b0);
            check_word(id, prdata, 32'h0000_0000);
        end
    endtask

    // ---------------- independent reference model ----------------
    function tb_mapped(input [7:0] a);
        begin
            tb_mapped = (a[1:0] == 2'b00) && (a < 8'h10);
        end
    endfunction

    function [31:0] tb_merge(input [31:0] old, input [31:0] data, input [3:0] strb);
        begin
            tb_merge = { (strb[3] ? data[31:24] : old[31:24]),
                         (strb[2] ? data[23:16] : old[23:16]),
                         (strb[1] ? data[15:8]  : old[15:8]),
                         (strb[0] ? data[7:0]   : old[7:0]) };
        end
    endfunction

    // ---------------- bus tasks ----------------
    task idle(input integer n);
        integer k;
        begin
            for (k = 0; k < n; k = k + 1) begin
                @(negedge pclk);
                psel    = 1'b0;
                penable = 1'b0;
                #1;
                quiet_check(10);
            end
        end
    endtask

    task apb_write(input [7:0] addr, input [31:0] data, input [3:0] strb);
        reg mapped_e;
        begin
            mapped_e = tb_mapped(addr);
            // setup phase
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b1;
            paddr   = addr;
            pwdata  = data;
            pstrb   = strb;
            #1;
            quiet_check(20);
            // access phase
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check_bit(21, pready, 1'b1);
            check_bit(22, pslverr, !mapped_e);
            check_word(23, prdata, 32'h0000_0000);
            if (mapped_e)
                model[addr[3:2]] = tb_merge(model[addr[3:2]], data, strb);
        end
    endtask

    task apb_read(input [7:0] addr);
        reg        mapped_e;
        reg [31:0] exp_data;
        begin
            mapped_e = tb_mapped(addr);
            exp_data = mapped_e ? model[addr[3:2]] : 32'h0000_0000;
            // setup phase
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = addr;
            pwdata  = 32'hA5A5_5A5A;
            pstrb   = 4'h0;
            #1;
            quiet_check(30);
            // access phase
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check_bit(31, pready, 1'b1);
            check_bit(32, pslverr, !mapped_e);
            check_word(33, prdata, exp_data);
        end
    endtask

    task read_all;
        begin
            apb_read(8'h00);
            apb_read(8'h04);
            apb_read(8'h08);
            apb_read(8'h0C);
        end
    endtask

    task do_reset(input integer n);
        integer k;
        begin
            @(negedge pclk);
            presetn = 1'b0;
            psel    = 1'b0;
            penable = 1'b0;
            for (k = 0; k < n; k = k + 1) begin
                #1;
                quiet_check(40);
                @(negedge pclk);
            end
            presetn  = 1'b1;
            model[0] = 32'h0000_0000;
            model[1] = 32'h0000_0000;
            model[2] = 32'h0000_0000;
            model[3] = 32'h0000_0000;
        end
    endtask

    task unmapped_writes;
        begin
            apb_write(8'h01, 32'hFFFF_FFFF, 4'hF);
            apb_write(8'h02, 32'hFFFF_FFFF, 4'hF);
            apb_write(8'h03, 32'hFFFF_FFFF, 4'hF);
            apb_write(8'h05, 32'hFFFF_FFFF, 4'hF);
            apb_write(8'h0D, 32'hFFFF_FFFF, 4'hF);
            apb_write(8'h10, 32'hFFFF_FFFF, 4'hF);
            apb_write(8'h14, 32'hFFFF_FFFF, 4'hF);
            apb_write(8'h18, 32'hFFFF_FFFF, 4'hF);
            apb_write(8'h1C, 32'hFFFF_FFFF, 4'hF);
            apb_write(8'h40, 32'hFFFF_FFFF, 4'hF);
            apb_write(8'h80, 32'hFFFF_FFFF, 4'hF);
            apb_write(8'hFC, 32'hFFFF_FFFF, 4'hF);
            apb_write(8'hFF, 32'hFFFF_FFFF, 4'hF);
        end
    endtask

    task unmapped_reads;
        begin
            apb_read(8'h01);
            apb_read(8'h02);
            apb_read(8'h03);
            apb_read(8'h05);
            apb_read(8'h0D);
            apb_read(8'h10);
            apb_read(8'h14);
            apb_read(8'h18);
            apb_read(8'h1C);
            apb_read(8'h40);
            apb_read(8'h80);
            apb_read(8'hFC);
            apb_read(8'hFF);
        end
    endtask

    // ---------------- verdict ----------------
    task verdict;
        begin
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        end
    endtask

    // ---------------- main sequence ----------------
    initial begin
        passed  = 0;
        failed  = 0;
        nonce   = {8*64{1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = {8*64{1'b0}};

        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = 8'h00;
        pwdata  = 32'h0000_0000;
        pstrb   = 4'h0;
        model[0] = 32'h0000_0000;
        model[1] = 32'h0000_0000;
        model[2] = 32'h0000_0000;
        model[3] = 32'h0000_0000;

        // Reset and reset values
        do_reset(3);
        idle(2);
        read_all;

        // Write then read every register, with idle gaps and back to back
        apb_write(8'h00, 32'h1111_1111, 4'hF);
        idle(1);
        apb_read(8'h00);
        idle(3);
        apb_write(8'h04, 32'h2222_2222, 4'hF);
        idle(2);
        apb_read(8'h04);
        apb_write(8'h08, 32'h3333_3333, 4'hF);
        apb_read(8'h08);
        apb_write(8'h0C, 32'h4444_4444, 4'hF);
        apb_read(8'h0C);
        read_all;

        // Back-to-back burst
        apb_write(8'h00, 32'hDEAD_BEEF, 4'hF);
        apb_write(8'h04, 32'hCAFE_F00D, 4'hF);
        apb_write(8'h08, 32'h0123_4567, 4'hF);
        apb_write(8'h0C, 32'h89AB_CDEF, 4'hF);
        apb_read(8'h0C);
        apb_read(8'h08);
        apb_read(8'h04);
        apb_read(8'h00);

        // All ones / all zeros
        apb_write(8'h00, 32'hFFFF_FFFF, 4'hF);
        apb_read(8'h00);
        apb_write(8'h00, 32'h0000_0000, 4'hF);
        apb_read(8'h00);

        // pstrb partial writes
        apb_write(8'h08, 32'h0000_0000, 4'hF);
        apb_write(8'h08, 32'hAABB_CCDD, 4'b0001);
        apb_read(8'h08);
        apb_write(8'h08, 32'h1122_3344, 4'b0010);
        apb_read(8'h08);
        apb_write(8'h08, 32'h5566_7788, 4'b0100);
        apb_read(8'h08);
        apb_write(8'h08, 32'h99AA_BBCC, 4'b1000);
        apb_read(8'h08);
        apb_write(8'h08, 32'hFFFF_FFFF, 4'b0101);
        apb_read(8'h08);
        apb_write(8'h08, 32'h0000_0000, 4'b1010);
        apb_read(8'h08);
        apb_write(8'h08, 32'h1234_5678, 4'b0110);
        apb_read(8'h08);
        apb_write(8'h08, 32'hFFFF_FFFF, 4'b0000);
        apb_read(8'h08);
        apb_write(8'h04, 32'h0000_0000, 4'b0000);
        apb_read(8'h04);
        read_all;

        // PSLVERR policy: unmapped writes change nothing
        unmapped_writes;
        read_all;
        idle(2);

        // PSLVERR policy: unmapped reads return zero
        unmapped_reads;
        read_all;

        // Reset again
        apb_write(8'h00, 32'h0F0F_0F0F, 4'hF);
        apb_write(8'h04, 32'hF0F0_F0F0, 4'hF);
        apb_write(8'h08, 32'h1357_9BDF, 4'hF);
        apb_write(8'h0C, 32'h2468_ACE0, 4'hF);
        read_all;
        idle(1);
        do_reset(2);
        idle(1);
        read_all;
        apb_write(8'h04, 32'h5A5A_A5A5, 4'hF);
        apb_read(8'h04);
        idle(3);

        verdict;
        $finish;
    end

    // Watchdog
    initial begin
        #1000000;
        failed = failed + 1;
        $error("check 50 failed: simulation timeout");
        verdict;
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
